description:
Implement `TupleToObject<T>` that converts a readonly tuple of string literals into an object type where each key and value is the same string literal.

**Example:**
```ts
type T = TupleToObject<['a', 'b', 'c']>;
// { a: 'a'; b: 'b'; c: 'c' }
```

Also implement `tupleToObject<T extends readonly string[]>(t: T): TupleToObject<T>` at runtime.

starter_code:
export type TupleToObject<T extends readonly string[]> = // your type here

export function tupleToObject<T extends readonly string[]>(t: T): TupleToObject<T> {
  // your code here
}

test_suite:
test('tupleToObject creates correct runtime object', () => {
  const result = tupleToObject(['a', 'b', 'c'] as const);
  expect(result).toEqual({ a: 'a', b: 'b', c: 'c' });
});

test('type-level: keys map to same string value', () => {
  type T = TupleToObject<['x', 'y']>;
  const check: T = { x: 'x', y: 'y' };
  expect(check).toEqual({ x: 'x', y: 'y' });
});

test('tupleToObject with single element', () => {
  const result = tupleToObject(['hello'] as const);
  expect(result).toEqual({ hello: 'hello' });
});

test('type-level: all tuple values become keys', () => {
  type T = TupleToObject<['foo', 'bar']>;
  type Keys = keyof T;
  const k1: Keys = 'foo';
  const k2: Keys = 'bar';
  expect(k1).toBe('foo');
  expect(k2).toBe('bar');
});

// __hidden__
test('tupleToObject with numbers-as-strings', () => {
  const result = tupleToObject(['1', '2'] as const);
  expect(result).toEqual({ '1': '1', '2': '2' });
});

solution:
export type TupleToObject<T extends readonly string[]> = { [K in T[number]]: K };

export function tupleToObject<T extends readonly string[]>(t: T): TupleToObject<T> {
  return Object.fromEntries(t.map(k => [k, k])) as TupleToObject<T>;
}
